@property
def _combined(self) -> IntervalSide:
    left = self.left._values
    right = self.right._values

    if isinstance(left, np.ndarray) and isinstance(right, np.ndarray):
        left_reshaped = left.reshape(-1, 1)
        right_reshaped = right.reshape(-1, 1)
    else:
        left_reshaped = left[:, None]
        right_reshaped = right[:, None]

    if needs_i8_conversion(left_reshaped.dtype):
        if isinstance(left_reshaped, np.ndarray):
            comb = np.concatenate([left_reshaped, right_reshaped], axis=1)
        else:
            comb = left._concat_same_type([left_reshaped, right_reshaped], axis=1)
        comb = comb.view("complex128")[:, 0]
    else:
        comb = (np.array(left_reshaped.ravel(), dtype="complex128")) + (
            1j * np.array(right_reshaped.ravel(), dtype="complex128")
        )

    return comb
